export default function LegoMethodItems() {
  const openDrawer = useMethodLinkInDrawer(paths.block.method.laq.key);
  
  const selectTarget = useItemCardSelectTarget(paths.block.method.laq.path());
  
  const { setItemsComponent } = useMenuContext();
  useEffect(() => {
    setItemsComponent([
      { title: '動くと面白い：', items: [
        { title: 'スライド式パーテーション', href: '#sliding-partition' },
        { title: '回転動作(回転角制限)', href: '#rotational-movement' },
      ]},
      { title: '組み方いろいろ：', items: [
        { title: '組み方(基本)', href: '#connection-01' },
        { title: '組み方(重ねる)', href: '#connection-02' },
        { title: '組み方(線画1)', href: '#connection-03' },
        { title: '組み方(線画2)', href: '#connection-04' },
        { title: '組み方(補強)', href: '#connection-05' },
      ]},
    ]);
  }, []);
  
  return (
    <MethodDrawerContent
      title='LaQ(ラキュー)のレシピ集'
      prelude={<Box>
          LaQ(ラキュー)の魅力は「ブロックが薄く弾力があり、ちょっと曲げてもつなげられる」ことだと思います。<br/>
          ただ「そう言われても何をどうすれば良いのか・・・」と悩んじゃうかもしれません。<br/>
          そんな時は "まず真似てみる" から始める方法があります。（"遊び"なので"直ぐに成果を求めない"のがポイントです）<br/>
          <br/>
          ここでは "素(もと)になるレシピ集" として、私が「何かに使えないかな」と色々と試したモノと、その思い付いたキッカケなどを紹介していきます。<br/>
          冒頭で紹介した「何に見える？」の連想ゲーム<AssociationGameRemark withinPortal withinScroll />と合わせて、「こうしたらカッコいいかも」とか
          身の回りの動物や道具へと少しずつ広げて頂ければと思います。<br/>
          見てくれた方々が「私だったらこうしよ〜」と、イメージを広げるキッカケとなれたなら、幸いです。
        </Box>}
      >
      <MyMethodMainArea>
        <Detail openDrawer={openDrawer} selectTarget={selectTarget} />
      </MyMethodMainArea>
    </MethodDrawerContent>
  )
}


import { MyMethodMainArea } from '~/ui/layout/MyMain'


type DetailProp = {
  openDrawer: (kind: string, name: string) => () => void;
  selectTarget :SelectTarget;
}
const Detail = memo(function Detail(prop: DetailProp) {
  const { openDrawer, selectTarget } = prop;
  return (
    <>
      <SectionCard title='動くと面白い' prelude={<>
        引き出すと扉になったりなど、しかけの素(もと)になるレシピ集です。<br/>
        これらを組み合わせたり、アレンジしたりして "ちょっと楽しめる" モノを作っていくイメージです。<br/>
        </>}
        >
        <SlidingPartition openDrawer={openDrawer} selectTarget={selectTarget} />
        <RotationalMovement openDrawer={openDrawer} selectTarget={selectTarget} />
      </SectionCard>
      <SectionCard title='組み方いろいろ' prelude={<>
        鍵盤に見えたり、顔に見えたりする組み方の素(もと)になるレシピ集です。<br/>
        他にも色々な工夫があるので、元々の用途にこだわらず、"何に見える？"<AssociationGameRemark withinPortal /> と思い付いたモノを作っていくイメージです。<br/>
        </>}
        >
        <Connection01 openDrawer={openDrawer} selectTarget={selectTarget} />
        <Connection02 openDrawer={openDrawer} selectTarget={selectTarget} />
        <Connection03 openDrawer={openDrawer} selectTarget={selectTarget} />
        <Connection04 openDrawer={openDrawer} selectTarget={selectTarget} />
        <Connection05 openDrawer={openDrawer} selectTarget={selectTarget} />
      </SectionCard>
    </>
  )
}, (prop1, prop2) => (prop1.openDrawer === prop2.openDrawer && prop1.selectTarget === prop2.selectTarget))

